export function renderAtmosphere(THREE,description){
 const group=new THREE.Group();group.name='presentation-atmosphere';group.userData={presentationOnly:true,description};const moving=[];let disposed=false;
 if(description.stars.length){const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(description.stars.flatMap(s=>[s.position.x,s.position.y,s.position.z]),3));group.add(new THREE.Points(geometry,new THREE.PointsMaterial({color:0xf1e8d7,size:1.5,sizeAttenuation:false})));}
 if(description.moon){const m=description.moon,moon=new THREE.Mesh(new THREE.SphereGeometry(m.radius,24,16),new THREE.MeshBasicMaterial({color:0xf4e7be}));moon.position.set(m.position.x,m.position.y,m.position.z);group.add(moon);for(let i=0;i<5;i++){const mark=new THREE.Mesh(new THREE.CircleGeometry(.18+i*.04,12),new THREE.MeshBasicMaterial({color:0xd5cbaa}));mark.position.set(-.8+i*.36,.5*Math.sin(i*2),1.94);moon.add(mark);}}
 for(const c of description.clouds){const cloud=new THREE.Group();cloud.position.set(c.position.x,c.position.y,c.position.z);const mat=new THREE.MeshStandardMaterial({color:description.time==='night'?0x535c77:0xe0e3df,roughness:1,transparent:true,opacity:.82});for(let i=0;i<5;i++){const puff=new THREE.Mesh(new THREE.IcosahedronGeometry(c.scale*(.6+i%3*.16),2),mat);puff.scale.set(1,.45,.65);puff.position.set((i-2)*c.scale*.65,Math.sin(i*2)*c.scale*.15,Math.cos(i)*c.scale*.2);cloud.add(puff);}group.add(cloud);moving.push({cloud,initial:c.position.x,phase:c.phase});}
 let drops=null;if(description.particles.length){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(description.particles.flatMap(p=>[p.x,p.y,p.z]),3));drops=new THREE.Points(g,new THREE.PointsMaterial({color:description.weather==='snow'?0xf3f4f8:0x8dbbe0,size:description.weather==='snow'?2.8:1.5,sizeAttenuation:false,transparent:true,opacity:.7,depthWrite:false}));group.add(drops);}
 group.traverse(o=>{if(o.isPoints){o.material.onBeforeCompile=shader=>{shader.fragmentShader=shader.fragmentShader.replace('#include <clipping_planes_fragment>', '#include <clipping_planes_fragment>\nif(length(gl_PointCoord-vec2(0.5))>0.5) discard;');};}});
 return{group,update(seconds){if(disposed)return;if(!Number.isFinite(seconds)||seconds<0)throw Error('Invalid atmosphere time');if(description.reducedMotion)return;for(const m of moving)m.cloud.position.x=m.initial+Math.sin(seconds*.035+m.phase)*description.windMetresPerSecond*4;if(drops){const a=drops.geometry.attributes.position;description.particles.forEach((p,i)=>{a.setY(i,2+((p.y-seconds*(description.weather==='snow'?1.2:15))%40+40)%40);});a.needsUpdate=true;}},dispose(){if(disposed)return;disposed=true;const geometries=new Set(),materials=new Set();group.traverse(o=>{if(o.geometry)geometries.add(o.geometry);for(const m of [].concat(o.material||[]))materials.add(m);});for(const g of geometries)g.dispose();for(const m of materials)m.dispose();group.removeFromParent();}};
}
